// Documentation (sitemap: Reference). Static content generated by guide.build.mjs from the
// solution documentation. The contents links scroll with scrollIntoView, because the model-driven
// app may size the page frame to its content, so a plain #anchor jump would not move anything.
import { applyStandard } from "../../shared/standard";

applyStandard();

document.querySelectorAll<HTMLAnchorElement>(".doc-toc a[href^='#']").forEach((link) => {
  link.addEventListener("click", (event) => {
    const target = document.getElementById(link.hash.slice(1));
    if (!target) return;
    event.preventDefault();
    target.scrollIntoView({ behavior: "smooth", block: "start" });
  });
});
